using namespace std;

int main() {
    int a[] = {3, 7, 2, 9, 1};
    int maxVal = a[0], minVal = a[0];
    for (int i = 1; i < 5; i++) {
        maxVal = max(maxVal, a[i]);
        minVal = min(minVal, a[i]);
    }
    cout << "max = " << maxVal << ", min = " << minVal << endl;
    return 0;
}

