#include <iostream>
using namespace std;

int main() {
    int n = 5;
    int dp[2][10] = {};
    dp[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        int cur = i % 2;
        int pre = 1 - cur;
        for (int j = 0; j < 10; j++) {
            dp[cur][j] = dp[pre][j] + (j > 0 ? dp[pre][j-1] : 0);
        }
    }
    cout << dp[n % 2][5] << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> vals = {100, 50, 200, 50, 100};
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    for (int i = 0; i < vals.size(); i++) {
        cout << vals[i] << " -> " << i << endl;
    }
    return 0;
}

